settings.liquid:
{%- comment -%}
  Scoped with section.id resolved at render time, not with a hardcoded template id.
  The brightening-glow page carries a style block written the other way and it has
  matched nothing ever since its template id changed.
{%- endcomment -%}
<style>
#shopify-section-{{ section.id }} .content-over-media > picture > img,
#shopify-section-{{ section.id }} .content-over-media > img { object-position: right center; }
@media screen and (min-width: 700px) {
  #shopify-section-{{ section.id }} .content-over-media > div { max-width: clamp(320px, 44vw, 640px); }
}
@media screen and (max-width: 699px) {
  #shopify-section-{{ section.id }} .content-over-media::before {
    background-image: linear-gradient(to bottom, rgba(10,14,22,0.86) 0%, rgba(10,14,22,0.66) 45%, rgba(10,14,22,0.55) 100%);
  }
}
</style>
